package com.bank.levels.model;

// Characteristics that drive the storage-level choice.
public class DatasetProfile {
    private final String name;
    private final boolean fitsInMemory;
    private final boolean expensiveToRecompute;
    private final boolean recomputeUnaffordable; // must never recompute (node loss)
    private final boolean gcSensitive;           // large cache causing GC pauses

    public DatasetProfile(String name, boolean fitsInMemory, boolean expensiveToRecompute,
                          boolean recomputeUnaffordable, boolean gcSensitive) {
        this.name = name;
        this.fitsInMemory = fitsInMemory;
        this.expensiveToRecompute = expensiveToRecompute;
        this.recomputeUnaffordable = recomputeUnaffordable;
        this.gcSensitive = gcSensitive;
    }
    public String getName() { return name; }
    public boolean fitsInMemory() { return fitsInMemory; }
    public boolean isExpensiveToRecompute() { return expensiveToRecompute; }
    public boolean isRecomputeUnaffordable() { return recomputeUnaffordable; }
    public boolean isGcSensitive() { return gcSensitive; }
}
