package com.bank.levels.storage;

// The main Spark storage levels and a short description of each.
public enum StorageLevel {
    MEMORY_ONLY("heap, deserialized; drops overflow → recompute"),
    MEMORY_AND_DISK("prefer memory, spill overflow to disk (safe default)"),
    MEMORY_AND_DISK_SER("spill to disk + serialized (packs ~3x tighter)"),
    DISK_ONLY("all partitions on disk (too big for memory)"),
    MEMORY_AND_DISK_2("memory+disk, replicated x2 (fault tolerant)"),
    OFF_HEAP("outside the JVM heap, avoids GC pressure");

    private final String description;
    StorageLevel(String description) { this.description = description; }
    public String description() { return description; }
}
