package com.bank.levels.storage;

import com.bank.levels.model.DatasetProfile;
import java.util.logging.Logger;

// Recommends a storage level from a dataset's profile.
public class LevelAdvisor {
    private static final Logger log = Logger.getLogger(LevelAdvisor.class.getName());

    public StorageLevel recommend(DatasetProfile p) {
        StorageLevel level;
        if (p.isRecomputeUnaffordable()) {
            level = StorageLevel.MEMORY_AND_DISK_2;        // replicate to avoid recompute
        } else if (p.isGcSensitive()) {
            level = StorageLevel.OFF_HEAP;                 // dodge GC on big caches
        } else if (!p.fitsInMemory() && p.isExpensiveToRecompute()) {
            level = StorageLevel.MEMORY_AND_DISK_SER;      // pack tight + spill
        } else if (!p.fitsInMemory()) {
            level = StorageLevel.DISK_ONLY;                // too big, cheap-ish to read
        } else if (p.isExpensiveToRecompute()) {
            level = StorageLevel.MEMORY_AND_DISK;          // safe default, no drop
        } else {
            level = StorageLevel.MEMORY_ONLY;              // small hot data, fastest
        }
        log.info(() -> "'" + p.getName() + "' → " + level + " (" + level.description() + ")");
        return level;
    }
}
