package com.bank.levels;

import com.bank.levels.model.DatasetProfile;
import com.bank.levels.storage.LevelAdvisor;
import java.util.List;
import java.util.logging.*;

public class LevelsDemo {
    private static final Logger log = Logger.getLogger(LevelsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new LevelsLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        LevelAdvisor advisor = new LevelAdvisor();
        List<DatasetProfile> datasets = List.of(
            // small hot lookup of account types for Rajesh/Priya
            new DatasetProfile("account_type_lookup", true,  false, false, false),
            // cleaned joined transactions feeding many reports (expensive, fits)
            new DatasetProfile("cleaned_txns",        true,  true,  false, false),
            // huge raw transaction history (does not fit, expensive to rebuild)
            new DatasetProfile("raw_txn_history",     false, true,  false, false),
            // ML training feature matrix, very expensive, must not recompute on loss
            new DatasetProfile("ml_feature_matrix",   true,  true,  true,  false),
            // massive cache causing GC pauses
            new DatasetProfile("wide_feature_cache",  true,  true,  false, true)
        );
        for (DatasetProfile d : datasets) advisor.recommend(d);
    }
}

